 dict(id='agreement',title='Identity versus reference coverage',headers=['Question','Pairwise identity','Reference coverage'],rows=[['What does it describe?','Agreement within aligned sequences','Extent of the reference represented'],['ALL-1','91.4%','0.8%'],['What it does not establish','Whole-chromosome observation','Accuracy or pathogenicity of every candidate']],source='§3.2.1'),
 dict(id='evidence',title='Annotation record versus validated somatic variant',headers=['Question','Annotation record','Validated somatic variant'],rows=[['Meaning','An entry in the descriptive summaries','A specified alteration with suitable evidence of somatic origin and validation'],['Can records repeat context?','Records may not represent independent alleles','Requires precise allele identity'],['Established here?','Yes, descriptive summaries','Not established for all summarized records']],source='§3.1.3; Discussion'),
