content=dict(version=1,name='Chromosome 9 Study Desk',subtitle='Understand the evidence. Explain the study.',studyTitle='Chromosome 9 Variant Annotation Profiles Across Public Acute Leukemia Sequencing Datasets',studyType='Secondary descriptive sequencing-data analysis',topics=topics,terms=terms,flashcards=cards,questions=questions,comparisons=comparisons,figures=figures,slides=slides,relationships=relationships,rehearsal=['State the objective without reading the slide.','Explain six runs versus four BioSamples.','Separate identity from coverage.','Describe counts without a significance claim.','Explain why group-restricted records are not biomarkers.','Interpret the closest clustering pair cautiously.','State the main limitations and next steps.'],discrepancies=[dict(title='Study type',detail='The build prompt calls this a review. The supplied manuscript is a secondary descriptive data analysis; a literature-review section is background.',source='Methods §3.1.1'),dict(title='Legacy figure terminology',detail='Several embedded figure titles use mutation, mutation burden or mutation profiles. The manuscript defines the summaries as annotation records rather than validated distinct somatic mutations.',source='Figures 1–7 and §3.1.3'),dict(title='Heat-map transformation',detail='Row-wise unit-variance scaling is reported, while the caption describes a 0–1 display. The exact transformation and imputation details require the original matrix/code.',source='§3.1.4; Figure 7'),dict(title='Presentation compression',detail='The oral and poster summaries omit many tool settings, coding-position lists and references. The manuscript remains the authority; omissions are not contradictory results.',source='Oral slides 1–10; poster sections'),dict(title='Missing contact/slot',detail='No corresponding-author email or assigned slot was supplied. Neither was invented.',source='Manuscript title page; presentation metadata')])
(R/'content/research.json').write_text(json.dumps(content,ensure_ascii=False,indent=2))
